    for (auto& v : g_a4OblAx) A4RST(v);
    for (auto& v : g_a4OblCos) A4RST(v);
    for (auto& v : g_a4NoOblAx) A4RST(v);
    A4RST(g_a4CausalSig);
    A4RST(g_a4NonAxSingle);
    A4RST(g_a4NonAxMulti);
    for (auto& v : g_a4NonAxCos) A4RST(v);
    A4RST(g_a4FLost);
    A4RST(g_a4FShort);
    for (auto& v : g_a4FLostCls) A4RST(v);
    for (auto& v : g_a4FShortCls) A4RST(v);
    A4RST(g_a4FSkip);
    for (auto& v : g_a4FShortRatio) A4RST(v);
    for (auto& v : g_a4FStructFam) A4RST(v);
    for (auto& v : g_a4FSliverFam) A4RST(v);
    for (auto& v : g_a4GStruct) A4RST(v);
    for (auto& v : g_a4GSliver) A4RST(v);
    A4RST(g_a4BoxHit);
