    for (auto& v : g_a4IStructBnd) A4RST(v);
    for (auto& v : g_a4ISliverBnd) A4RST(v);
    for (auto& v : g_a4JStruct) A4RST(v);
    for (auto& v : g_a4JSliver) A4RST(v);
    A4RST(g_a4JChordSum);
    A4RST(g_a4JWalkSum);
    for (auto& v : g_a4KStructBox) A4RST(v);
    for (auto& v : g_a4KStructWall) A4RST(v);
    for (auto& v : g_a4KSliverBox) A4RST(v);
    for (auto& v : g_a4KNoChordFam) A4RST(v);
    for (auto& v : g_a4KDefEqWall) A4RST(v);
    for (auto& v : g_a4KOppWallZero) A4RST(v);
