    // isSmall 的复制态镜像（阈值同式同短路序 ⇒ 全秩与 owner-fresh 同判定）
    auto isSmallFromMeta = [&](int ci) -> bool {
        const CellRec& cr = cells[(size_t)ci];
        if (cr.removed) return false;
        if (cr.splitPiece) return false;   // H14 已回退（见 isSmall 处实录）
        const double h3 = cr.h * cr.h * cr.h;
        if (cr.vol < cfg.mergeVolFrac * h3) return true;
        if (cr.cut || cr.merged)
            if (dt.metMinFW[(size_t)ci] < 0.05 * cr.h) return true;
        if (cr.cut && !cr.merged && cr.vol > 0 && !dt.metCenIn[(size_t)ci]) return true;
        if (cr.cut && !cr.merged && cr.vol > 0) {
            for (int nb : dt.adj[(size_t)ci]) {
                const CellRec& ncr = cells[(size_t)nb];
                if (!ncr.removed && ncr.vol > 100.0 * cr.vol) return true;
            }
        }
        if (cr.vol > 0 && (cr.cut || cr.merged) && dt.metFoam[(size_t)ci] > planeTolE1)
            return true;
        return false;
    };
